def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def normalize_email(value):
        value = value.strip()

        # If angle brackets are present, use their contents.
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")

        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        # Ignore the extension marker and everything after it.
        value = re.split(r"(?i:ext|x|#)", value, maxsplit=1)[0]
        digits = "".join(character for character in value if character.isdigit())

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in ("0", "1"):
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()

        match = re.fullmatch(r"(\d{5})-\d{4}", value)
        if match:
            value = match.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def normalize_source(value):
        return value.strip().lower()

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value)
            if tag.strip()
        }

    normalized_rows = []

    for input_index, row in enumerate(rows):
        normalized = {
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "source": normalize_source(row["source"]),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
            "input_index": input_index,
        }

        # Discard rows with neither a valid email nor a valid phone.
        if normalized["email"] or normalized["phone"]:
            normalized_rows.append(normalized)

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized_rows):
        email = row["email"]
        if email:
            if email in email_owner:
                union(index, email_owner[email])
            else:
                email_owner[email] = index

        # last_name is compared case-insensitively.
        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_last_name_owner:
                union(index, phone_last_name_owner[key])
            else:
                phone_last_name_owner[key] = index

    groups = {}
    for index, row in enumerate(normalized_rows):
        root = find(index)
        groups.setdefault(root, []).append(row)

    def preferred_value(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = min(
            candidates,
            key=lambda row: (
                0 if row["source"] == "manual" else 1,
                -row["updated_dt"].timestamp(),
                row["input_index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        tags = set()
        opted_out = False

        for row in group:
            tags.update(row["tags"])
            opted_out = opted_out or row["opted_out"]

        latest_updated = max(row["updated_dt"] for row in group)

        output.append(
            {
                "first_name": preferred_value(group, "first_name"),
                "last_name": preferred_value(group, "last_name"),
                "zip": preferred_value(group, "zip"),
                "email": preferred_value(group, "email"),
                "phone": preferred_value(group, "phone"),
                "source": preferred_value(group, "source"),
                "tags": ";".join(sorted(tags)),
                "opted_out": "Y" if opted_out else "N",
                "updated": latest_updated.strftime("%Y-%m-%d"),
                "_earliest_index": min(row["input_index"] for row in group),
            }
        )

    output.sort(key=lambda person: person["_earliest_index"])

    for person in output:
        del person["_earliest_index"]

    return output
